use crate::report::{dropped_items, role_source, ExportReport, PreservedItem};
use palette16::{color, Base16Palette};
use semantic_roles::{role_color, Role, SemanticRoles};
use theme_ir::{ResolvedTheme, Warning};

pub fn export_mc_skin(
    theme: &ResolvedTheme,
    roles: &SemanticRoles,
    palette: &Base16Palette,
    warnings: Vec<Warning>,
) -> (String, ExportReport) {
    let mut output = String::new();
    output.push_str("[skin]\n");
    output.push_str(&format!(
        "    description = {} - generated by Themeforge\n",
        theme.name
    ));
    output.push_str("    truecolors = true\n");
    output.push('\n');
    output.push_str("[Lines]\n");
    for (key, value) in mc_lines() {
        output.push_str(&format!("    {key} = {value}\n"));
    }

    for section in mc_sections() {
        output.push('\n');
        output.push_str(&format!("[{}]\n", section.name));
        for entry in section.entries {
            output.push_str(&format!(
                "    {} = {}\n",
                entry.key,
                render_entry(&entry, roles, palette)
            ));
        }
    }

    let report = ExportReport {
        exporter: "mc".to_owned(),
        source: theme.source_path.to_string(),
        preserved: mc_preserved_items(roles),
        dropped: mc_dropped_items(theme),
        warnings,
    };
    (output, report)
}

#[derive(Debug, Clone)]
struct McSection {
    name: &'static str,
    entries: Vec<McEntry>,
}

#[derive(Debug, Clone, Copy)]
struct McEntry {
    key: &'static str,
    fg: McColor,
    bg: McColor,
    attrs: &'static [&'static str],
}

#[derive(Debug, Clone, Copy)]
struct McColor {
    roles: &'static [Role],
    fallback_base: &'static str,
}

impl McColor {
    const fn new(roles: &'static [Role], fallback_base: &'static str) -> Self {
        Self {
            roles,
            fallback_base,
        }
    }
}

const BACKGROUND: McColor = McColor::new(&[Role::Background], "base00");
const SURFACE: McColor = McColor::new(&[Role::Surface], "base01");
const SELECTION: McColor = McColor::new(&[Role::Selection], "base02");
const FOREGROUND: McColor = McColor::new(&[Role::Foreground], "base05");
const MUTED_FOREGROUND: McColor = McColor::new(&[Role::MutedForeground], "base03");
const BRIGHT_FOREGROUND: McColor = McColor::new(&[Role::BrightForeground], "base07");
const FUNCTION: McColor = McColor::new(&[Role::Function], "base0D");
const TYPE: McColor = McColor::new(&[Role::Type], "base0A");
const VARIABLE: McColor = McColor::new(&[Role::Variable, Role::Function], "base0D");
const STRING: McColor = McColor::new(&[Role::String], "base0B");
const NUMBER: McColor = McColor::new(&[Role::Number], "base09");
const CONSTANT: McColor = McColor::new(&[Role::Constant], "base09");
const SPECIAL: McColor = McColor::new(&[Role::Special], "base0C");
const ERROR: McColor = McColor::new(&[Role::Error], "base08");
const WARNING: McColor = McColor::new(&[Role::Warning, Role::Type], "base0A");
const GIT_ADDED: McColor = McColor::new(&[Role::GitAdded], "base0B");
const GIT_MODIFIED: McColor = McColor::new(&[Role::GitModified, Role::Warning], "base0A");
const GIT_REMOVED: McColor = McColor::new(&[Role::GitRemoved, Role::Error], "base08");

const BOLD: &[&str] = &["bold"];
const ITALIC: &[&str] = &["italic"];
const UNDERLINE: &[&str] = &["underline"];

fn mc_lines() -> &'static [(&'static str, &'static str)] {
    &[
        ("horiz", "─"),
        ("vert", "│"),
        ("lefttop", "┌"),
        ("righttop", "┐"),
        ("leftbottom", "└"),
        ("rightbottom", "┘"),
        ("topmiddle", "┬"),
        ("bottommiddle", "┴"),
        ("leftmiddle", "├"),
        ("rightmiddle", "┤"),
        ("cross", "┼"),
        ("dhoriz", "═"),
        ("dvert", "║"),
        ("dlefttop", "╔"),
        ("drighttop", "╗"),
        ("dleftbottom", "╚"),
        ("drightbottom", "╝"),
        ("dtopmiddle", "╤"),
        ("dbottommiddle", "╧"),
        ("dleftmiddle", "╟"),
        ("drightmiddle", "╢"),
    ]
}

const fn entry(key: &'static str, fg: McColor, bg: McColor, attrs: &'static [&str]) -> McEntry {
    McEntry { key, fg, bg, attrs }
}

